// ─────────────────────────────────────────────────────────────────────────────
// Pri Learning · the generated iPad web bundles carry only the flags that ship.
//
// ios/*/Resources/Web is what the native shell ships. Since decision D28 it is
// generated by `npm run build && npm run sync:ios` and never tracked, so this
// check runs where the bundle is generated: the CI build job, the App Health
// agent and the release-candidate lane, right after the sync (it is no longer
// part of the sharded `npm test`, which builds nothing). Features outside the
// frozen V1 scope (docs/release/PRI_V1_RELEASE_SCOPE.md) are build flags that
// test builds switch on, so a bundle synced from a test build would ship them.
// Each build writes the flags it was made with to features.json; this check
// fails unless both bundles carry that manifest with every flag off, and unless
// the entry chunk is the one that publishes the resolved flags. A bundle that
// was not generated fails here too; absence is never a pass.
//
// The one exception is SHIPPABLE_FEATURE_FLAGS (vite.config.js): a flag the
// owner may turn on at GO. Such a flag must equal what THIS environment asked
// the build for (PRI_FEATURE_<NAME>=1 → on, anything else → off), so a tutor-on
// release build passes, and a tutor-on test build synced into a flag-off
// release still fails.
//
// The student interface is not a flag: client/interface.config.mjs sets it for
// every build (V1 decision D7). Each bundle must record exactly that interface
// and skin, so the iPhone and iPad apps ship what the web and Android builds
// ship.
//
// Usage: npm run build && npm run sync:ios && node client/test/ios-bundle-features-check.mjs
// ─────────────────────────────────────────────────────────────────────────────
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { FEATURE_FLAGS, INSTRUMENT_BUILD, SHIPPABLE_FEATURE_FLAGS } from '../vite.config.js';
import { STUDENT_INTERFACE, INTERFACE_SKIN } from '../interface.config.mjs';

const ROOT = fileURLToPath(new URL('../../', import.meta.url));
export const BUNDLES = ['PriLearning.swiftpm', 'PriLearning 2.swiftpm'].map(b => [b, join(ROOT, 'ios', b, 'Resources', 'Web')]);

/** The value each FEATURE_FLAG must have in a shipped bundle, under `env`. */
export function expectedFlags(env = process.env) {
  return Object.fromEntries(FEATURE_FLAGS.map(name =>
    [name.toLowerCase(), SHIPPABLE_FEATURE_FLAGS.includes(name) && env[`PRI_FEATURE_${name}`] === '1']));
}

export function checkBundles(bundles = BUNDLES, env = process.env) {
  let pass = 0;
  const failures = [];
  const ok = (name, cond, detail = '') => (cond ? pass++ : failures.push(`${name}${detail ? ` — ${detail}` : ''}`));
  const want = expectedFlags(env);
  for (const [label, web] of bundles) {
    const file = join(web, 'features.json');
    ok(`${label}: carries features.json`, existsSync(file), existsSync(web) ? 'bundle not generated — run npm run build && npm run sync:ios' : 'Resources/Web is missing');
    if (!existsSync(file)) continue;
    let flags = null;
    try { flags = JSON.parse(readFileSync(file, 'utf8')); } catch { flags = null; }
    ok(`${label}: features.json is readable`, !!flags && typeof flags === 'object');
    if (!flags) continue;
    for (const [name, on] of Object.entries(want)) {
      ok(`${label}: records the ${name} flag`, typeof flags[name] === 'boolean', JSON.stringify(flags));
      ok(on ? `${label}: ${name} is on, as this release build asked (PRI_FEATURE_${name.toUpperCase()}=1)` : `${label}: ${name} is off in the shipped bundle`,
        flags[name] === on, JSON.stringify(flags));
    }
    ok(`${label}: ships the one student interface (${STUDENT_INTERFACE})`, flags.instrument === INSTRUMENT_BUILD, JSON.stringify(flags));
    ok(`${label}: wears the skin the setting names (${INTERFACE_SKIN})`, flags.skin === INTERFACE_SKIN, JSON.stringify(flags));
    const assets = join(web, 'assets');
    const entry = existsSync(assets) ? readdirSync(assets).filter(f => /^index-[^/]*\.js$/.test(f)) : [];
    ok(`${label}: has one entry chunk`, entry.length === 1, entry.join(','));
    if (entry.length === 1) {
      const src = readFileSync(join(assets, entry[0]), 'utf8');
      ok(`${label}: the entry chunk publishes the resolved flags`, src.includes('__PRI_BUILD_FEATURES__'));
    }
  }
  return { pass, failures, on: Object.keys(want).filter(k => want[k]) };
}

if (process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url) {
  const { pass, failures, on } = checkBundles();
  if (failures.length) {
    for (const f of failures) console.log('  ✖ ' + f);
    console.log(`IOS BUNDLE FEATURES: FAIL — ${pass}/${pass + failures.length} checks. Rebuild without PRI_FEATURE_* set (npm run build), or with only the shippable flags the release asks for, then npm run sync:ios; the bundles are generated, never committed.`);
    process.exit(1);
  }
  console.log(`IOS BUNDLE FEATURES: PASS — ${pass}/${pass} checks — both generated iPad bundles are ${on.length ? `production builds with only ${on.join(', ')} on, as the release asked` : `flag-off production builds of the ${STUDENT_INTERFACE} interface`}.`);
}
